def count_Substring_With_Equal_Ends(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            if s[i] == s[j - 1]:
                count += 1
    return count

def is_Monotonic(arr):
    if len(arr) <= 1:
        return True
    increasing = True
    decreasing = True
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            decreasing = False
        if arr[i] < arr[i - 1]:
            increasing = False
    return increasing or decreasing

