def find_length(s, k):
    n = len(s)
    if n < k:
        return 0
    max_diff = 0
    for i in range(n - k + 1):
        sub = s[i:i+k]
        count0 = sub.count('0')
        count1 = sub.count('1')
        diff = abs(count0 - count1)
        if diff > max_diff:
            max_diff = diff
    return max_diff

