def find_Min(arr, start, end):
    if start == end:
        return arr[start]
    if start > end:
        return float('inf')
    mid = (start + end) // 2
    if arr[mid] >= arr[start]:
        return find_Min(arr, mid + 1, end)
    else:
        return min(arr[mid], find_Min(arr, start, mid - 1))

def amicable_numbers_sum(n):
    def get_divisors(num):
        divisors = set()
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divisors.add(i)
                if i != num // i and num // i != num:
                    divisors.add(num // i)
        return sum(divisors) - num

    def is_amicable(a, b):
        if a == b:
            return False
        sum_a = get_divisors(a)
        sum_b = get_divisors(b)
        return sum_a == b and sum_b == a

    amicable_set = set()
    for i in range(1, n + 1):
        if i in amicable_set:
            continue
        sum_i = get_divisors(i)
        if sum_i != i:
            j = sum_i
            if j > i and j <= n:
                if is_amicable(i, j):
                    amicable_set.add(i)
                    amicable_set.add(j)
    return sum(amicable_set)

