def longest_common_subsequence(s1, s2, m, n):
    if m == 0 or n == 0:
        return ""
    if s1[m-1] == s2[n-1]:
        return s1[m-1] + longest_common_subsequence(s1, s2, m-1, n-1)
    else:
        lcs1 = longest_common_subsequence(s1, s2, m, n-1)
        lcs2 = longest_common_subsequence(s1, s2, m-1, n)
        return lcs1 if len(lcs1) > len(lcs2) else lcs2

