        return 0
    dp = [0] * n
    for j in range(i + 1, k):
        if arr[j] > arr[i]:
            dp[j] = arr[j] + dp[j - 1]
    for j in range(k + 1, n):
        if arr[j] > arr[i]:
            dp[j] = arr[j] + dp[j - 1]
    for j in range(i + 1, k):
        if arr[j] > arr[i]:
            dp[j] = max(dp[j], dp[j - 1] + arr[j])
    for j in range(k + 1, n):
        if arr[j] > arr[i]:
            dp[j] = max(dp[j], dp[j - 1] + arr[j])
    return max(dp[i + 1:k] + [0], default=0) + max(dp[k+1:n] + [0], default=0) if k < n else 0

