def compute_Last_Digit(a, b):
    if a > b:
        return 0
    if a == 0:
        return 1
    if b == 0:
        return 0
    if a == 1:
        return 1
    if b == 1:
        return 0

    # Calculate factorial of a
    fact_a = 1
    for i in range(2, a + 1):
        fact_a *= i

    # Calculate factorial of b
    fact_b = 1
    for i in range(2, b + 1):
        fact_b *= i

    return fact_b % fact_a

