def rearange_string(s):
    from collections import Counter
    counts = Counter(s)
    max_count = max(counts.values())
    total = len(s)
    if max_count > (total + 1) // 2:
        return None
    result = []
    for char in sorted(counts.keys(), key=lambda x: -counts[x]):
        count = counts[char]
        for _ in range(count):
            result.append(char)
    result.sort()
    return ''.join(result)

def check_subset_list(subset_list, superset_list):
    def is_subset(sub, sup):
        if not isinstance(sub, list) or not isinstance(sup, list):
            return False
        if len(sub) > len(sup):
            return False
        for i in range(len(sub)):
            if sub[i] not in sup:
                return False
        return True

    for item in subset_list:
        if not is_subset(item, superset_list):
            return False
    return True

def sum_digits_twoparts(n):
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n == 0:
        return 0
    s = str(n)
    max_sum = 0
    for i in range(len(s)):
        part1 = int(s[:i+1])
        part2 = int(s[i+1:])
        sum_digits = sum_digits(part1) + sum_digits(part2)
        if sum_digits > max_sum:
            max_sum = sum_digits
    return max_sum

