def search(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            if mid == 0 or arr[mid - 1] != arr[mid]:
                return arr[mid]
            else:
                left = mid + 1
        else:
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
    return -1

def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, dict_depth(v) + 1)
        else:
            max_depth = max(max_depth, 0)
    return max_depth

