def max_sum(arr, k):
    n = len(arr)
    if n == 0:
        return 0
    inc = [0] * n
    dec = [0] * n
    inc[0] = arr[0]
    dec[0] = arr[0]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])
            if arr[j] > arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])
    max_val = 0
    for i in range(n):
        if inc[i] + dec[i] - arr[i] > max_val:
            max_val = inc[i] + dec[i] - arr[i]
    return max_val

