def max_sub_array_sum_repeated(arr, k, m):
    if not arr:
        return 0
    max_so_far = float('-inf')
    current_sum = 0
    for x in arr:
        current_sum += x
        if current_sum > max_so_far:
            max_so_far = current_sum
        if current_sum < 0:
            current_sum = 0
    max_prefix = float('-inf')
    max_suffix = 0
    current_prefix = 0
    current_suffix = 0
    for x in arr:
        current_prefix += x
        if current_prefix > max_prefix:
            max_prefix = current_prefix
        current_suffix += x
        if current_suffix < 0:
            current_suffix = 0
    max_suffix = max(max_suffix, current_suffix)
    total_sum = sum(arr)
    if total_sum > 0:
        max_sum = max(max_prefix + max_suffix, max_so_far)
        for i in range(2, k):
            max_sum += total_sum
    else:
        max_sum = max(max_so_far, max_prefix + max_suffix)
    return max_sum

