def bell_number(n):
    if n == 0:
        return 1
    B = [[0] * (n + 1) for _ in range(n + 1)]
    B[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            B[i][j] = B[i - 1][j - 1] + sum(B[i - 1][k] for k in range(j, i))
    return B[n][0]

