def max_profit(prices, k):
    if not prices or k == 0:
        return 0
    n = len(prices)
    if n <= 1:
        return 0
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit
    dp = [[0] * (k + 1) for _ in range(n)]
    for i in range(1, n):
        for j in range(1, k + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + prices[i] - prices[i - 1])
    return dp[n - 1][k]

