    max_val = max(arr)
    min_val = min(arr)
    range_val = max_val - min_val + 1
    count = [0] * range_val
    for num in arr:
        count[num - min_val] += 1
    result = []
    for i in range(range_val):
        result.extend([i + min_val] * count[i])
    return result

