    def helper(n):
        if n in memo:
            return memo[n]
        if n == 0:
            return 0
        res = n
        for i in [2, 3, 4, 5]:
            if n % i == 0:
                res = max(res, helper(n // i) + helper(n // i) + helper(n // i) + helper(n // i))
        memo[n] = res
        return res

    return helper(n)

