def find_rotation_count(arr):
    if not arr:
        return 0
    if arr[0] <= arr[-1]:
        return 0
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    return low

def binomial_probability(n, k, p):
    from math import comb
    return comb(n, k) * (p ** k) * ((1 - p) ** (n - k))

