def max_sum(triangle, n):
    for i in range(n - 2, -1, -1):
        for j in range(i + 1):
            triangle[i][j] = max(triangle[i][j], triangle[i + 1][j], triangle[i + 1][j + 1])
    return triangle[0][0]

def div_even_odd(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    if not evens or not odds:
        return None
    return sum(evens) / sum(odds)

