        return None
    n = len(arr)
    if k < 0:
        k = k % n
    if k == 0:
        return arr[index]
    rotated = arr[-k:] + arr[:-k]
    return rotated[index]

def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    a, b, c = 0, 1, 2
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

import re

def check_char(s):
    if not s:
        return "Invalid"
    pattern = r'^(.)(.*)\1$'
    if re.match(pattern, s):
        return "Valid"
    return "Invalid"

def magic_square_test(square):
    n = len(square)
    if n == 0:
        return True
    if n % 2 == 0:
        return False
    for row in square:
        if sum(row) != n * (n + 1) // 2:
            return False
    for i in range(n):
        if sum(square[i][i]) != n * (n + 1) // 2:
            return False
        if sum(square[i][n - 1 - i]) != n * (n + 1) // 2:
            return False
    for i in range(n):
        if sum(square[j][i] for j in range(n)) != n * (n + 1) // 2:
            return False
    for i in range(n):
        for j in range(n):
            if square[i][j] < 1 or square[i][j] > n or square[i][j] != i + 1:
                return False
    return True

def re_arrange_array(arr, n):
    result = [0] * n
    neg_idx = 0
    pos_idx = n - 1
    for i in range(n):
        if arr[i] < 0:
            result[neg_idx] = arr[i]
            neg_idx += 1
        else:
            result[pos_idx] = arr[i]
            pos_idx -= 1
    return result

