def cal_electbill(kwh):
    if kwh <= 100:
        return kwh * 3.15
    elif kwh <= 200:
        return 100 * 3.15 + (kwh - 100) * 3.25
    else:
        return 100 * 3.15 + 100 * 3.25 + (kwh - 200) * 3.35

def find_length(s, k):
    if not s or k <= 0:
        return 0
    n = len(s)
    if k > n:
        return 0
    max_diff = 0
    for i in range(n):
        count0 = 0
        count1 = 0
        for j in range(i, min(i + k, n)):
            if s[j] == '0':
                count0 += 1
            else:
                count1 += 1
        diff = abs(count0 - count1)
        if diff > max_diff:
            max_diff = diff
    return max_diff

