        return a
    if n == 2:
        return a * r
    if n == 3:
        return a * r * r
    if n == 4:
        return a * r * r * r
    if n == 5:
        return a * r * r * r * r
    if n == 6:
        return a * r * r * r * r * r
    if n == 7:
        return a * r * r * r * r * r * r
    if n == 8:
        return a * r * r * r * r * r * r * r
    if n == 9:
        return a * r * r * r * r * r * r * r * r
    if n == 10:
        return a * r * r * r * r * r * r * r * r * r
    if n == 11:
        return a * r * r * r * r * r * r * r * r * r * r
    if n == 12:
        return a * r * r * r * r * r * r * r * r * r * r * r
    if n == 13:
