def find_Min(arr, start, end):
    if start == end:
        return arr[start]
    if start < end:
        mid = (start + end) // 2
        if arr[mid] < arr[end]:
            return arr[mid]
        if arr[start] < arr[mid]:
            return arr[start]
        return find_Min(arr, mid + 1, end)
    return arr[start]

def amicable_numbers_sum(n):
    def get_divisors(num):
        divs = []
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divs.append(i)
                if i != num // i and i != 1:
                    divs.append(num // i)
        return divs

    def get_sum_of_divisors(num):
        return sum(get_divisors(num))

    def is_amicable(a, b):
        if a == b:
            return False
        if get_sum_of_divisors(a) != b or get_sum_of_divisors(b) != a:
            return False
        return True

    total = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if is_amicable(i, j):
                total += i + j
    return total

