def get_maxgold(grid, rows, cols):
    if not grid or rows <= 0 or cols <= 0:
        return 0
    dp = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            dp[i][j] = grid[i][j]
    for i in range(1, rows):
        for j in range(cols):
            dp[i][j] = grid[i][j] + max(dp[i-1][j], dp[i-1][j-1] if j > 0 else 0)
    return max(max(row) for row in dp)

def is_undulating(s):
