def max_len_sub(arr, k):
    if not arr:
        return 0
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
        for j in range(1, k + 1):
            for l in range(i):
                if abs(arr[i] - arr[l]) == j:
                    dp[i][j] = max(dp[i][j], dp[l][j])
    return max(max(row) for row in dp)

