def longest_common_subsequence(s1, s2, m, n):
    if m == 0 or n == 0:
        return 0
    if s1[m-1] == s2[n-1]:
        return 1 + longest_common_subsequence(s1, s2, m-1, n-1)
    else:
        return max(longest_common_subsequence(s1, s2, m, n-1), longest_common_subsequence(s1, s2, m-1, n))

def sum_difference(n):
