def max_sum_increasing_subseq(arr, n, k, i):
    if k <= i or i >= n:
        return 0
    dp = [0] * n
    for j in range(i + 1, n):
        if arr[j] > arr[i]:
            dp[j] = arr[j] + dp[i]
    for j in range(i + 1, n):
        if arr[j] > arr[i]:
            dp[j] = max(dp[j], dp[j - 1])
    return max(dp[i + 1:]) if dp[i + 1:] else 0

def odd_Equivalent(s, n):
    count = 0
    for i in range(n):
        temp = ""
        for j in range(len(s)):
            temp += s[(j + i) % len(s)]
        if int(temp, 2) % 2 == 1:
            count += 1
    return count

def smallest_missing(arr, start, end):
    if start > end:
        return start
    if arr[start] != start:
        return start
    if arr[end] != end:
        return end
    for i in range(start, end):
        if arr[i] != i:
            return i
    return end + 1

