def max_path_sum(triangle, start_row, start_col):
    if not triangle or not triangle[start_row]:
        return 0
    if start_row == len(triangle) - 1:
        return triangle[start_row][start_col]
    left = max_path_sum(triangle, start_row + 1, start_col)
    right = max_path_sum(triangle, start_row + 1, start_col + 1)
    return triangle[start_row][start_col] + max(left, right)

def is_subset_sum(arr, target_sum, max_val):
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]
