def find_minimum_range(arrays):
    if not arrays:
        return (0, 0)
    n = len(arrays)
    if n == 1:
        return (min(arrays[0]), max(arrays[0]))
    sorted_arrays = [sorted(arr) for arr in arrays]
    min_idx = [0] * n
    max_idx = [0] * n
    current_min = sorted_arrays[0][0]
    current_max = sorted_arrays[0][0]
    min_range = float('inf')
    result = (0, 0)
    for _ in range(len(sorted_arrays[0])):
        current_max = max(sorted_arrays[i][max_idx[i]] for i in range(n))
        current_min = min(sorted_arrays[i][min_idx[i]] for i in range(n))
        if current_max - current_min < min_range:
            min_range = current_max - current_min
            result = (current_min, current_max)
        for i in range(n):
            while max_idx[i] < len(sorted_arrays[i]) - 1 and sorted_arrays[i][max_idx[i] + 1] <= sorted_arrays[i][min_idx[i]]:
                max_idx[i] += 1
            min_idx[i] += 1
    return result

