def rearange_string(s):
    if len(s) == 0:
        return ""
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    max_count = max(counts.values())
    if max_count > (len(s) + 1) // 2:
        return None
    result = []
    for i in range(0, len(s), 2):
        for char in counts:
            if counts[char] > 0:
                result.append(char)
                counts[char] -= 1
                break
    for i in range(1, len(s), 2):
        for char in counts:
            if counts[char] > 0:
                result.append(char)
                counts[char] -= 1
                break
    return "".join(result)

