def check_subset_list(subset, superset):
    if not isinstance(subset, list) or not isinstance(superset, list):
        return False
    if len(subset) == 0:
        return True
    if len(superset) < len(subset):
        return False
    for i in range(len(subset)):
        if not isinstance(subset[i], list):
            return False
        if not isinstance(superset[i], list):
            return False
        if len(subset[i]) > len(superset[i]):
            return False
        for j in range(len(subset[i])):
            if subset[i][j] != superset[i][j]:
                return False
    return True

