def zigzag(n, k):
    if n == 1:
        return 1
    if n == 2:
        return 2
    if k == 1:
        return n
    if k == n:
        return n
    if k == 0:
        return 0
    if k > n:
        return 0
    if n % 2 == 0:
        return (n // 2) * k + (n // 2)
    else:
        return (n // 2) * k + (n // 2) + 1

