def max_sub_array_sum_repeated(arr, k, m):
    if not arr:
        return 0
    total_sum = sum(arr)
    if total_sum <= 0:
        max_single = max(arr)
        return max_single * m if max_single > 0 else 0

    max_sub = float('-inf')
    current = 0
    for x in arr:
        current += x
        if current > max_sub:
            max_sub = current
        if current < 0:
            current = 0

    return max_sub * m + total_sum * (k - 2) if k > 2 else max_sub * k

def max_Abs_Diff(arr, k):
    if not arr:
        return 0
    max_val = arr[0]
    min_val = arr[0]
    for x in arr:
        if x > max_val:
            max_val = x
        if x < min_val:
            min_val = x
    diff = max_val - min_val
    if diff > k:
        return k
    return diff

