def find_adverb_position(sentence):
    import re
    words = sentence.split()
    adverbs = []
    for i, word in enumerate(words):
        if re.match(r'^\w+$', word) and word[0].isupper():
            adverbs.append((i, word))
    if not adverbs:
        return None
    return adverbs[0]

