def max_profit(prices, k):
    if not prices or k == 0:
        return 0
    n = len(prices)
    if n <= 1:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i-1][j]
            for t in range(1, i):
                profit = prices[i-1] - prices[t-1] + dp[t][j-1]
                if profit > dp[i][j]:
                    dp[i][j] = profit
    return dp[n][k]

