    pos = [x for x in arr if x > 0]
    neg = [x for x in arr if x < 0]
    zero = [x for x in arr if x == 0]
    result = []
    i = 0
    while i < len(arr):
        if i % 2 == 0:
            if i < len(neg):
                result.append(neg[i])
            else:
                result.append(zero[i // 2] if i // 2 < len(zero) else 0)
        else:
            if i < len(pos):
                result.append(pos[i])
            else:
                result.append(zero[i // 2] if i // 2 < len(zero) else 0)
        i += 1
    return result

