def min_Ops(arr, k, n):
    if k == 0:
        return 0
    if n == 0:
        return 0
    if len(arr) != n:
        return 0
    target = sum(arr) // n
    if target == 0:
        return 0
    ops = 0
    for x in arr:
        if x > target:
            ops += x - target
        elif x < target:
            ops += target - x
    return ops % k if ops % k != 0 else ops

