        if i < len(lst) - 1:
            result.append(element)
    return result

def is_num_keith(n):
    if n < 1:
        return False
    if n == 1:
        return True
    seq = list(n)
    while len(seq) < len(n):
        next_val = sum(seq[-len(n):])
        seq.append(next_val)
    if seq[-1] != n:
        return False
    for i in range(len(seq)):
        if seq[i] == 0:
            return False
    return True

def kth_element(arr, k, index):
    arr.sort()
    return arr[k - index]

def find_rotation_count(arr):
    if not arr:
        return 0
    if arr[0] <= arr[-1]:
        return 0
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    rotation = (low + 1) % len(arr)
    return rotation

def tuple_to_int(t):
    result = 0
    for i in range(len(t)):
        result = result * 10 + t[i]
    return result

def larg_nnum(data, n):
    if n <= 0:
        return []
    if n >= len(data):
        return sorted(data, reverse=True)
    sorted_data = sorted(data, reverse=True)
    return sorted_data[:n]

def concatenate_tuple(t):
    result = ""
    for i in range(len(t)):
        if i > 0:
            result += "-"
        result += str(t[i])
    return result

import math

def binomial_probability(n, k, p):
    if k < 0 or k > n:
        return 0.0
    if p == 0 or p == 1:
        return 1.0 if (p == 1 and k <= n) or (p == 0 and k == 0) else 0.0
    return math.factorial(n) / (math.factorial(k) * math.factorial(n - k)) * (p ** k) * ((1 - p) ** (n - k))

def upper_ctr(s):
    count = 0
    for char in s:
        if char.isupper():
            count += 1
    return count

def string_literals(literals, text):
    if not literals:
        return 'Matched!'
    for lit in literals:
        if lit in text:
            return 'Matched!'
    return 'Not matched'

def find_Nth_Digit(n, a, b):
    if a == 0:
        return 0
    if b == 0:
        return 0
    if n == 0:
        return 0
    result = 0
    for i in range(1, n + 1):
        a = (a * 10) % b
        result = result * 10 + a
    return result % 10

def binary_search(arr, target):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return True
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

def assign_freq(tuples):
    result = []
    seen = {}
    for t in tuples:
        key = t
        if key in seen:
            seen[key] += 1
        else:
            seen[key] = 1
        result.append((t, seen[key]))
    return result

def heap_assending(lst):
    import heapq
    result = []
    for item in lst:
        heapq.heappush(result, item)
    return result

def frequency_lists(lst):
    counts = {}
    for sublist in lst:
        for item in sublist:
            if item in counts:
                counts[item] += 1
            else:
                counts[item] = 1
    return counts

def get_max_occuring_char(s):
    if not s:
        return ""
    max_char = s[0]
    max_count = 0
    for char in s:
        count = 0
        for c in s:
            if c == char:
                count += 1
        if count > max_count:
            max_count = count
            max_char = char
    return max_char

def max_sum(triangle, n):
    for i in range(n - 1, 0, -1):
        for j in range(i):
            triangle[j] = triangle[j] + triangle[j + 1]
    return triangle[0]

def count_Occurrence(t, lst):
