            result[item] = result.get(item, 0) + 1
    return result

def Find_Min(lst):
    if not lst:
        return []
    min_len = len(lst[0])
    min_sub = lst[0]
    for item in lst:
        if len(item) < min_len:
            min_len = len(item)
            min_sub = item
    return min_sub

