def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    a, b, c = 0, 1, 2
    for i in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

