def re_arrange_array(arr, n):
    result = []
    for i in range(len(arr)):
        if arr[i] < 0:
            result.append(arr[i])
        else:
            result.append(arr[i])
    return result[:n]

def count_Substring_With_Equal_Ends(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            if s[i] == s[j - 1]:
                count += 1
    return count

def angle_complex(x, y):
    import math
    if x == 0 and y == 0:
        return 0.0
    if x > 0:
        return math.atan2(y, x)
    elif x < 0 and y >= 0:
        return math.atan2(y, x) + math.pi
    else:
        return math.atan2(y, x) - math.pi

def permutation_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

def check_occurences(tuples_list):
    result = {}
    for i in range(len(tuples_list)):
        for j in range(i + 1, len(tuples_list)):
            if tuples_list[i][0] == tuples_list[j][0] and tuples_list[i][1] == tuples_list[j][1]:
                key = (tuples_list[i][0], tuples_list[i][1])
                result[key] = result.get(key, 0) + 1
    return result

def same_order(list1, list2):
    if not list1 or not list2:
        return True
    common = []
    for i in range(len(list1)):
        if list1[i] in list2:
            common.append(list1[i])
    if len(common) == 0:
        return True
    for i in range(len(common) - 1):
        if common[i] == common[i+1]:
            return False
    return True

def first_non_repeating_character(s):
    counts = {}
    for char in s:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    for char in s:
        if counts[char] == 1:
            return char
    return None

def list_split(lst, n):
    result = []
    for i in range(n):
        sub = []
        for j in range(0, len(lst), n):
            if j % n == i:
                sub.append(lst[j])
        result.append(sub)
    return result

def dict_filter(data, threshold):
    result = {}
    for key, value in data.items():
        if value >= threshold:
            result[key] = value
    return result
